insert into public.exercises (id, name, notes, youtube_id, clip_path) values (13125871, 'Landmine Single Leg Squat', 'Every week you''ll perform more sets and reps. The goal is to use the same weight every week.', null, 'sltp/13125871') on conflict (id) do update set name = excluded.name, notes = excluded.notes, youtube_id = excluded.youtube_id, clip_path = coalesce(public.exercises.clip_path, excluded.clip_path), updated_at = now();
insert into public.exercises (id, name, notes, youtube_id, clip_path) values (13125877, 'DB Hammer Curls - Short Jump Squats', 'Perform the prescribed reps as fast as possible, then log how long it took you to complete both exercises.
insert into public.exercises (id, name, notes, youtube_id, clip_path) values (13125880, 'Banded Rear Flyes - Banded Tricep Pushdowns', 'Perform these 2 warmup exercises in a row without stopping in between
insert into public.exercises (id, name, notes, youtube_id, clip_path) values (13125882, 'Plyo Pushups off Bench', 'Go all out with this exercise - meaning, really EXPLODE up off the bench.
insert into public.exercises (id, name, notes, youtube_id, clip_path) values (13125883, 'DB Incline Bench Press', 'This is one of the greatest exercises you can do for building nice shoulders, arms, and fixing your posture.
