insert into public.exercises (id, name, notes, youtube_id, clip_path) values (13125886, 'DB Incline Skullcrushers', 'These Skullcrushers are your ''Finisher'' for Phase 1 Day 2 - the goal is to choose a ''nice'' weight that you like
insert into public.exercises (id, name, notes, youtube_id, clip_path) values (13125888, 'Pallof Press - Single Leg Ring Squat', 'Perform the Pallof press and Single Leg Squats in a row without stopping in between
insert into public.exercises (id, name, notes, youtube_id, clip_path) values (13125889, 'Kettlebell Swings', 'This is not only your opportunity to WAKE up your butt (so that it''s active for the hip thrusts coming up)
