insert into public.exercises (id, name, notes, youtube_id, clip_path) values (13125961, 'Barbell Squat', 'Some say this is the ''king'' of all exercises - and I could agree...
insert into public.exercises (id, name, notes, youtube_id, clip_path) values (13125962, 'DB Step-Up', 'Very important to NOT use your bottom foot to lift yourself off here. Let most of your ''force'' come from the foot that''s on the bench.
insert into public.exercises (id, name, notes, youtube_id, clip_path) values (13125967, 'Barbell Standing Curls - Bodyweight Bulgarians', 'Since the Bulgarians in this Finisher are bodyweight (don''t underestimate them), you will only need to track the weight on the Barbell curls.
insert into public.exercises (id, name, notes, youtube_id, clip_path) values (13125968, 'Single Arm Row - Strippers - Skiers', 'You do use weight on the Incline Skiers, but no need to track it.
