insert into public.exercises (id, name, notes, youtube_id, clip_path) values (13126050, 'Lateral Hurdle Jumps', 'Get violent and explosive on these - and increase the length or height you jump every week.', null, 'sltp/13126050') on conflict (id) do update set name = excluded.name, notes = excluded.notes, youtube_id = excluded.youtube_id, clip_path = coalesce(public.exercises.clip_path, excluded.clip_path), updated_at = now();
